package vn.edu.eaut.lab10.controller;
import java.io.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import vn.edu.eaut.lab10.model.User;import vn.edu.eaut.lab10.repository.UserRepository;
@WebServlet("/user/password") public class PasswordController extends HttpServlet{private final UserRepository r=new UserRepository();protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{q.getRequestDispatcher("/user/password.jsp").forward(q,p);}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{User u=(User)q.getSession().getAttribute("currentUser");String old=q.getParameter("oldPassword"),n=q.getParameter("newPassword"),c=q.getParameter("confirmPassword");if(!u.getPassword().equals(old))q.setAttribute("error","Mật khẩu cũ không đúng.");else if(n==null||n.length()<6)q.setAttribute("error","Mật khẩu mới tối thiểu 6 ký tự.");else if(!n.equals(c))q.setAttribute("error","Xác nhận mật khẩu không khớp.");else{u.setPassword(n);r.update(u);q.getSession().setAttribute("currentUser",u);q.setAttribute("success","Đổi mật khẩu thành công.");}q.getRequestDispatcher("/user/password.jsp").forward(q,p);}}